import base64

img1_b64 = ""
img1_b64 += "=" * ((4 - len(img1_b64) % 4) % 4)

img2_b64 = ""
img2_b64 += "=" * ((4 - len(img2_b64) % 4) % 4)

with open("src/assets/images/retrait_colis.jpg", "wb") as f:
    f.write(base64.b64decode(img1_b64))

with open("src/assets/images/mondial_relay_logo_2.png", "wb") as f:
    f.write(base64.b64decode(img2_b64))
